import java.util.Locale;

/**
 * FloorGroup — drop-in p500.Group view of the FloorBench JNI-floor lanes
 * (task B11). Contract-compatible with the P500 harness group format
 * (bench/p500/java/p500/Group.java + the G&lt;gid&gt; classes generated by
 * gen_p500_bench.py):
 *
 *   fqcn() / sig() / methods() / setup(int) / call(int)
 *
 * Purpose: classes defined via c-crussty injection land in the bootstrap
 * loader of the LIVE server JVM. If the Crussty CE .so files cannot be
 * System.load'ed outside the CRUSSTY runtime on some future build, the
 * floor lanes can still be measured inside the injected server JVM by
 * driving THIS class through the same machinery p500.Bench uses
 * (setup(strategy) -> probe -> warmup -> time-bounded batches -> SINK).
 * p500.Bench itself hardcodes Class.forName("G" + gid), so driving
 * FloorGroup needs a ~10-line driver loop (see reports/B11) or a future
 * one-line Bench extension; the measured semantics are identical.
 *
 * Lane order is FIXED (do not reshuffle — call(int) switches on it):
 *   0..3   java baselines (emptyStatic, emptyStatic4args, sinkFold, nanoTime)
 *   4..8   JNI floor kernels (P500 g32/g35/g39/g42/g33, all < 150 ns)
 *   9      JNI climate kernel (P500 g06 subtractFirstDistanceSum)
 *   10..12 java-approx climate reconstructions (NOT verified parity)
 *
 * Native lanes (4..9) throw UnsatisfiedLinkError in a JVM without the
 * Crussty CE libs — p500.Bench probe logic treats that per-method, so
 * the java lanes still measure. Args are the P500 strategy-0 shapes,
 * rebuilt per setup() call; call(int) is ONE lane call folded like the
 * generated groups (acc*31 + dst0^dst1).
 */
public final class FloorGroup implements p500.Group {

    static final String[] METHODS = {
            "java_emptyStatic",
            "java_emptyStatic4args",
            "java_sinkVolatileFold",
            "java_nanoTimeCall",
            "jni_g32_PluginNameLog_newArrayListSortSummary",
            "jni_g35_RangeChoice_oldFillArraySummary",
            "jni_g39_SpigotLoadOrderDependency_newLoadAfterBuildSummary",
            "jni_g42_StaticCacheGet_oldBatchSummary",
            "jni_g33_PluginStartupRollup_newSummary",
            "jni_g06_ClimateParameterDistance_subtractFirstDistanceSum",
            "javaApproxClimateDistanceSum_unpacked6x10",
            "javaApproxSubtractFirst_raw",
            "javaApproxTouch3Arrays",
    };

    @Override public String fqcn() { return "FloorBench"; }
    @Override public String sig() { return "(floor-lanes)"; }
    @Override public String[] methods() { return METHODS.clone(); }

    /** strategy is accepted for contract parity; shapes are fixed P500
     *  strategy-0 (N = -Dfloor.n, default 256). Fresh args every setup. */
    @Override public void setup(int strategy) {
        FloorBench.buildArgs();
    }

    @Override public long call(int idx) {
        long acc;
        switch (idx) {
            // ---- LANE-A: pure Java ----
            case 0 -> acc = FloorBench.emptyStatic();
            case 1 -> acc = FloorBench.emptyStatic4args(
                    FloorBench.aInt, FloorBench.aObj1, FloorBench.aObj2, FloorBench.aDst);
            case 2 -> { long v = FloorBench.SINK; FloorBench.SINK = v + 1L; acc = v; }
            case 3 -> { long t = System.nanoTime(); acc = t ^ (t >>> 32); }
            // ---- LANE-B: JNI floor kernels (P500 sub-150ns set) ----
            case 4 -> acc = FloorBench.fold(PaperNativePluginNameLog.newArrayListSortSummary(
                    FloorBench.aInt, FloorBench.aObj1, FloorBench.aObj2, FloorBench.aDst));
            case 5 -> acc = FloorBench.fold(PaperNativeRangeChoice.oldFillArraySummary(
                    FloorBench.aD0, FloorBench.aI1, FloorBench.aI2, FloorBench.aI3,
                    FloorBench.aInt, FloorBench.aDst));
            case 6 -> acc = FloorBench.fold(PaperNativeSpigotLoadOrderDependency.newLoadAfterBuildSummary(
                    FloorBench.aInt, FloorBench.aObj1, FloorBench.aDst));
            case 7 -> acc = FloorBench.fold(PaperNativeStaticCacheGet.oldBatchSummary(
                    FloorBench.aInt, FloorBench.SMALL[1], FloorBench.SMALL[2],
                    FloorBench.SMALL[3], FloorBench.SMALL[4], FloorBench.aI5, FloorBench.aDst));
            case 8 -> acc = FloorBench.fold(PaperNativePluginStartupRollup.newSummary(
                    FloorBench.aInt, FloorBench.aObj1, FloorBench.aTmpDir,
                    FloorBench.aObj2, FloorBench.aObj3, FloorBench.aDst));
            // ---- LANE-C: native climate vs java-approx ----
            case 9 -> acc = FloorBench.fold(PaperNativeClimateParameterDistance.subtractFirstDistanceSum(
                    FloorBench.aC0, FloorBench.aC1, FloorBench.aC2, FloorBench.aDst));
            case 10 -> acc = FloorBench.fold(FloorBench.javaApproxClimateDistanceSum(
                    FloorBench.aC0, FloorBench.aC1, FloorBench.aC2, FloorBench.aDst));
            case 11 -> acc = FloorBench.fold(FloorBench.javaApproxSubtractFirstRaw(
                    FloorBench.aC0, FloorBench.aC1, FloorBench.aC2, FloorBench.aDst));
            case 12 -> acc = FloorBench.fold(FloorBench.javaApproxTouch(
                    FloorBench.aC0, FloorBench.aC1, FloorBench.aC2, FloorBench.aDst));
            default -> acc = 0L;
        }
        return acc;
    }

    /** Tiny standalone driver mirroring p500.Bench's per-group loop — lets
     *  FloorGroup run through the exact P500 methodology without touching
     *  p500.Bench. Usage: java -cp ... FloorGroup [-Dfloor.libs=...]. */
    public static void main(String[] argv) {
        for (String p : System.getProperty("floor.libs", "").split(java.io.File.pathSeparator))
            if (!p.isBlank()) System.load(p);
        FloorGroup g = new FloorGroup();
        long sink = 0;
        int n = g.methods().length;
        // probe
        g.setup(0);
        boolean[] usable = new boolean[n];
        for (int i = 0; i < n; i++) {
            try { sink += g.call(i); usable[i] = true; }
            catch (Throwable t) {
                System.err.println("probe " + g.methods()[i] + ": " + t.getClass().getSimpleName());
            }
        }
        // measure (forward + reverse, min-of-medians — p500.Bench fairness rule)
        double[] medF = onePass(g, usable, false);
        double[] medR = onePass(g, usable, true);
        for (int i = 0; i < n; i++) {
            if (!usable[i]) {
                System.out.printf(Locale.ROOT, "RESULT\t%s\tfloor-group\tFloorBench\t(floor-lanes)\t-\t-\t-\tERR-or-NO-NATIVE%n",
                        g.methods()[i]);
                continue;
            }
            double m = Math.min(medF[i], medR[i]);
            System.out.printf(Locale.ROOT, "RESULT\t%s\tfloor-group\tFloorBench\t(floor-lanes)\t%.1f\t%.1f\t%.1f\tOK%n",
                    g.methods()[i], m, m, m);
        }
        System.out.println("SINK\t" + (FloorBench.SINK + sink));
        System.out.flush();
    }

    static double[] onePass(FloorGroup g, boolean[] usable, boolean reverse) {
        String[] names = g.methods();
        double[] med = new double[names.length];
        for (int x = 0; x < names.length; x++) {
            int i = reverse ? names.length - 1 - x : x;
            if (!usable[i]) continue;
            g.setup(0);
            // fixed-count warmup: 2x40µs batches do NOT reach C2 thresholds for
            // java-side lanes (measured: java-approx raw lane 1304ns under-warmed
            // vs ~66ns at 200k warmup calls — p500.Bench never noticed because
            // its lanes are all native, where only the caller loop needs heat).
            for (int w = 0; w < 200_000; w++) FloorBench.SINK += g.call(i);
            double[] s = new double[5];
            for (int r = 0; r < 5; r++) s[r] = runBatch(g, i, 120_000);
            java.util.Arrays.sort(s);
            med[i] = s[s.length / 2];
        }
        return med;
    }

    static double runBatch(FloorGroup g, int idx, long budgetNs) {
        long calls = 0, t0 = System.nanoTime(), el;
        do {
            for (int k = 0; k < 8; k++) FloorBench.SINK += g.call(idx);
            calls += 8;
            el = System.nanoTime() - t0;
        } while (el < budgetNs);
        return (double) el / calls;
    }
}
